{"content": """"Shared types and the Adapter base contract.

Everything in the stack funnels through :class:`Adapter.run`, which takes a
:class:`~opensciencelab.manifest.Manifest` and a
:class:`~opensciencelab.manifest.Budget`, returns a
:class:`Bundle` (artifacts + cost), and records itself against the manifest.
That single choke point is what makes provenance and budgeting trivial.
"""
from __future__ import annotations

import hashlib
import json
import time
import uuid
from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Optional

# --------------------------------------------------------------------------- #
# Cost model                                                                    #
# --------------------------------------------------------------------------- #
# Compute is tiered. Costs are abstract "units" (not dollars); a real deployment
# maps them to $ by tier in Budget. Higher tier = slower / more expensive, used
# on fewer candidates.
TIER_ZERO, TIER_ONE, TIER_TWO = 0, 1, 2
DEFAULT_TIER_COSTS = {TIER_ZERO: 0.01, TIER_ONE: 1.0, TIER_TWO: 50.0}


def _now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


# --------------------------------------------------------------------------- #
# Data types                                                                    #
# --------------------------------------------------------------------------- #
@dataclass
class Candidate:
    """A thing being scored (molecule / complex / crystal)."""

    id: str
    kind: str = "molecule"  # molecule | complex | crystal
    smi: Optional[str] = None
    pdb_id: Optional[str] = None
    seq: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Candidate":
        return cls(**d)


@dataclass
class ScoreVector:
    """A set of named metric values for a candidate.

    By convention **higher is better** for every key here; a scoring adapter is
    responsible for flipping sign on metrics that are naturally "lower-better"
    (e.g. docking energy) before constructing this object.
    """

    metrics: Dict[str, float] = field(default_factory=dict)
    tier: int = TIER_ZERO

    def get(self, name: str, default: float = 0.0) -> float:
        return self.metrics.get(name, default)

    def to_dict(self) -> Dict[str, Any]:
        return {"tier": self.tier, "metrics": self.metrics}

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "ScoreVector":
        return cls(metrics=dict(d.get("metrics", {})), tier=d.get("tier", TIER_ZERO))


def _sha256(obj: Any) -> str:
    blob = json.dumps(obj, sort_keys=True, default=str).encode("utf-8")
    return hashlib.sha256(blob).hexdigest()


@dataclass
class Artifact:
    """An immutable product of an adapter call, with a stable identity hash."""

    id: str
    kind: str  # e.g. "structure", "design_seqs", "scores", "pareto", "report"
    service: str
    service_version: str
    created_at: str
    payload: Dict[str, Any] = field(default_factory=dict)
    files: List[str] = field(default_factory=list)  # relative paths under run dir

    def digest(self) -> str:
        return _sha256(
            {
                "id": self.id,
                "kind": self.kind,
                "service": self.service,
                "service_version": self.service_version,
                "payload": self.payload,
            }
        )

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["digest"] = self.digest()
        return d


@dataclass
class Bundle:
    """What every adapter returns: artifacts, the manifest patch, and cost."""

    artifacts: List[Artifact] = field(default_factory=list)
    manifest_patch: Dict[str, Any] = field(default_factory=dict)
    cost: Dict[int, float] = field(default_factory=dict)  # tier -> units used

    def total_cost(self) -> float:
        return sum(self.cost.values())


# --------------------------------------------------------------------------- #
# Adapter contract + registry                                                 #
# --------------------------------------------------------------------------- #
class Adapter(ABC):
    """Base class for all services.

    Subclasses set ``name`` and ``version`` and implement :meth:`_exec`. The
    wrapper :meth:`run` handles the boilerplate — recording the call, charging
    the budget, and attaching the service identity to every Artifact.
    """

    name: str = "adapter"
    version: str = "0.0.0"

    # ---- subclass implements this ----
    @abstractmethod
    def _exec(self, manifest, budget, **inputs) -> Bundle:
        raise NotImplementedError

    # ---- public entry point ----
    def run(self, manifest, budget, **inputs) -> Bundle:
        from .manifest import BudgetExceeded  # local import to avoid cycle

        bundle = self._exec(manifest, budget, **inputs)

        # charge budget (validated) for each tier used
        for tier, cost in bundle.cost.items():
            budget.spend(int(tier), float(cost))

        # stamp artifacts with this service identity
        for art in bundle.artifacts:
            if not art.service:
                art.service = self.name
            if not art.service_version:
                art.service_version = self.version

        # record a single entry for this call
        manifest.record(
            service=self.name,
            version=self.version,
            call=inputs,
            cost=bundle.cost,
            artifacts=[a.id for a in bundle.artifacts],
        )
        manifest.merge_patch(bundle.manifest_patch)
        return bundle


_REGISTRY: Dict[str, Adapter] = {}


def register(adapter: Adapter) -> None:
    _REGISTRY[adapter.name] = adapter


def get(name: str) -> Adapter:
    if name not in _REGISTRY:
        raise KeyError(
            f"unknown adapter {name!r}; registered: {sorted(_REGISTRY)}"
        )
    return _REGISTRY[name]


def registered() -> List[str]:
    return sorted(_REGISTRY)


def new_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:10]}"
