{"content": """"Adapter registry + the four service surfaces.

Lazy imports inside each getter so that a missing optional dependency (RDKit,
Boltz, OpenEvolve, ...) never breaks module import — only the specific call.
"""
from __future__ import annotations

from typing import Any, Dict, List

from ..base import (  # noqa: F401  (re-exported)
    Adapter,
    Artifact,
    Bundle,
    Candidate,
    ScoreVector,
    new_id,
    registry,
)
from . import structure, design, scoring, optimize  # noqa: F401

# --------------------------------------------------------------------------- #
# Registry registration (idempotent)                                          #
# --------------------------------------------------------------------------- #
_structure = structure.Boltz2Adapter()
_design = design.RFdiffusionProteinMPNNAdapter()
_score = scoring.TieredScoringAdapter()
_optimize = optimize.OpenEvolveAdapter()

for _a in (_structure, _design, _score, _optimize):
    registry.register(_a)

# --------------------------------------------------------------------------- #
# Service facades — "one entry point" per the buildout plan                   #
# --------------------------------------------------------------------------- #
class StructureService:
    """Predict protein / complex structures.

    Primary: Boltz-2 (MIT). Alternates: Chai-1 (antibody-antigen SOTA),
    ESMFold (no-MSA fast path). All behind the same I/O contract.
    """

    name = "structure.boltz2"

    def predict(self, manifest, budget, input_, model: str = "boltz2") -> Bundle:
        adapter = registry.get(self._model_key(model))
        return adapter.run(manifest, budget, sequence=input_"seq" if isinstance(input_, dict) else input_, model=model)

    @staticmethod
    def _model_key(model: str) -> str:
        return {
            "boltz2": "structure.boltz2",
            "chai1": "structure.boltz2",  # same adapter, different backend
            "esmfold": "structure.boltz2",
        }.get(model, "structure.boltz2")


class DesignService:
    """De novo protein design: RFdiffusion (scaffold) + ProteinMPNN (sequence)."""

    name = "design.rfmpnn"

    def design(self, manifest, budget, **kw) -> Bundle:
        return registry.get(self.name).run(manifest, budget, **kw)


class ScoreService:
    """Tiered scoring. tier=0 (RDKit/QED) -> tier=1 (docking) -> tier=2 (QM).

    Costs are drawn per-call from Budget.costs[tier]. Higher tier = slower/more
    expensive, used on fewer candidates. This is the "Claude Science flexible
    compute" analogue.
    """

    name = "score.tiered"

    def score(self, manifest, budget, candidates, tier: int = 0) -> Bundle:
        return registry.get(self.name).run(
            manifest, budget, candidates=candidates, tier=tier
        )


class OptimizeService:
    """OpenEvolve-backed evolutionary optimization.

    This is the "engine" of the stack — the thing that turns a seed program +
    a tiered ScoreService into a Pareto front of candidates.
    """

    name = "optimize.openevolve"

    def evolve(self, manifest, budget, initial_program, **kw) -> Bundle:
        return registry.get(self.name).run(
            manifest, budget, initial_program=initial_program, **kw
        )
