{"content": """"Service facades + adapter registry (the "one entry point" contract).

Design rule from the buildout plan: nothing in the stack talks to another tool
directly; all capabilities go through the four facades, and every adapter call
is recorded against the run :class:`~opensciencelab.manifest.Manifest`.

Optional heavy dependencies (RDKit, Boltz, OpenEvolve, PySCF, MACE) are imported
lazily *inside* their adapters, so a missing install only removes that adapter
from the registry — it never breaks module import.
"""
from __future__ import annotations

from typing import Any, Dict, List, Callable

from ..base import (  # noqa: F401  (re-exported)
    Adapter,
    Artifact,
    Bundle,
    Candidate,
    ScoreVector,
    new_id,
)
from .base import REGISTRY as _REG  # noqa: F401


def available() -> List[str]:
    return sorted(_REG)


def _bootstrap() -> None:
    """Import concrete adapters; each self-registers on import."""
    from . import structure, design, scoring, optimize  # noqa: F401


# Register adapters eagerly. Import failures for optional deps are swallowed per
# module and logged once at call time via KeyError('adapter not found').
try:
    _bootstrap()
except Exception:  # pragma: no cover - defensive; shouldn't happen
    import traceback

    traceback.print_exc()


# --------------------------------------------------------------------------- #
# Facades                                                                     #
# --------------------------------------------------------------------------- #
class StructureService:
    """Predict protein / complex structure.

    Backends: Boltz-2 (MIT) or Chai-1 (antibody-antigen SOTA).
    ``input_`` is one of:

    - a plain sequence string  (monomer)
    - ``{"chains": [{"seq": "...", "name": "A"}, ...]}`` (complex)
    - ``{"seq": "...", "smi": "CCO"}`` (protein-ligand)
    """

    name = "structure"

    @staticmethod
    def _adapter(model: str) -> Adapter:
        model = (model or "boltz2").lower()
        if model in ("boltz2", "boltz"):
            return _REG.get("structure.boltz2") or _raise("structure.boltz2")
        if model in ("chai1", "chai"):
            return _REG.get("structure.chai1") or _raise("structure.chai1")
        if model == "esmfold":
            return _REG.get("structure.esmfold") or _raise("structure.esmfold")
        raise ValueError(f"unknown structure model: {model!r}")

    def predict(self, manifest, budget, input_, model: str = "boltz2") -> Bundle:
        return self._adapter(model).run(manifest, budget, input=input_)


class DesignService:
    """De novo protein design: RFdiffusion scaffold + ProteinMPNN sequence."""

    name = "design"

    def design(
        self, manifest, budget, target_structure, n_seqs: int = 4, **kw
    ) -> Bundle:
        adapter = _REG.get("design.rfmpnn") or _raise("design.rfmpnn")
        return adapter.run(
            manifest, budget, target_structure=target_structure, n_seqs=n_seqs, **kw
        )


class ScoreService:
    """Tiered scoring.

    - tier 0 (RDKit fast descriptors) — cheap, local
    - tier 1 (docking / ML surrogate) — mid, GPU
    - tier 2 (QM via PySCF / long dock) — expensive, GPU/HPC

    Cost = :data:`Budget.costs`[tier] * n_candidates, charged per call so the
    budget ledger stays honest.
    """

    name = "score"

    @staticmethod
    def _adapter(tier: int) -> Adapter:
        if tier not in (0, 1, 2):
            raise ValueError(f"tier must be 0, 1 or 2 (got {tier!r})")
        keys = {0: "score.tier0_rdkit", 1: "score.tier1_surrogate", 2: "score.tier2_pyscf"}
        return _REG.get(keys[tier]) or _raise(keys[tier])

    def score(
        self, manifest, budget, candidates: List[Candidate], tier: int = 0
    ) -> Bundle:
        return self._adapter(tier).run(manifest, budget, candidates=candidates)


class OptimizeService:
    """OpenEvolve-backed evolutionary optimization.

    ``initial_program`` — seed code the LLM will mutate.
    ``evaluator`` — ``Callable[[Candidate], ScoreVector]`` (or a name of a
    registered evaluator; the adapter resolves both).
    ``iterations`` — number of OpenEvolve generations to run.
    """

    name = "optimize"

    def evolve(
        self,
        manifest,
        budget,
        initial_program: str,
        evaluator: Any,
        iterations: int = 10,
        **kw,
    ) -> Bundle:
        adapter = _REG.get("optimize.openevolve") or _raise("optimize.openevolve")
        return adapter.run(
            manifest,
            budget,
            initial_program=initial_program,
            evaluator=evaluator,
            iterations=iterations,
            **kw,
        )


def _raise(name: str) -> Adapter:
    raise KeyError(
        f"adapter {name!r} is not registered. "
        f"Available: {available() or '<none>'}. "
        "Install the optional dependency it needs, e.g. `pip install opensciencelab[boltz]`."
    )


def services() -> Dict[str, Any]:
    """Return the four facades bundled into one dict, for one-liners."""
    return {
        "structure": StructureService(),
        "design": DesignService(),
        "score": ScoreService(),
        "optimize": OptimizeService(),
    }


__all__ = [
    "StructureService",
    "DesignService",
    "ScoreService",
    "OptimizeService",
    "services",
    "available",
]
