{"content": """"Service facades — the "one entry point" layer of the stack.

Nothing in the platform talks to a backend tool directly; everything goes
through these four facades, and every adapter call is recorded on the run
manifest with its cost.
"""
from __future__ import annotations

from typing import Any, Dict, List

from .base import (  # noqa: F401  (re-exported for user convenience)
    Adapter,
    Bundle,
    Candidate,
    ScoreVector,
    registry,
)


class StructureService:
    """Predict protein / complex structure.

    Backends: Boltz-2 (MIT) or Chai-1 (antibody-antigen SOTA).
    ``input_`` is one of:

    - a plain sequence string                     → monomer
    - ``{"chains": [{"seq": ..., "name": ...}]}`` → complex
    - ``{"seq": ..., "smi": "CCO"}``              → protein-ligand complex
    """

    name = "structure"

    @staticmethod
    def _adapter(model: str) -> Adapter:
        model = (model or "boltz2").lower()
        if model in ("boltz2", "boltz"):
            return registry.get("structure.boltz2")
        if model in ("chai1", "chai"):
            return registry.get("structure.chai1")
        if model == "esmfold":
            return registry.get("structure.esmfold")
        raise ValueError(f"unknown structure model: {model!r}")

    def predict(self, manifest, budget, input_, model: str = "boltz2") -> Bundle:
        return self._adapter(model).run(manifest, budget, input=input_)


class DesignService:
    """De novo protein design (RFdiffusion scaffold + ProteinMPNN sequence)."""

    name = "design"

    def design(
        self, manifest, budget, target_structure, n_seqs: int = 4, **kw
    ) -> Bundle:
        adapter = registry.get("design.rfmpnn")
        return adapter.run(
            manifest, budget, target_structure=target_structure, n_seqs=n_seqs, **kw
        )


class ScoreService:
    """Tiered scoring.

    - tier 0: fast descriptors (RDKit QED/SA; heuristic fallback) — cheap, local
    - tier 1: docking / ML surrogate — mid, GPU
    - tier 2: QM (PySCF) — expensive, GPU/HPC

    Cost per call = costs[tier] * (n candidates), charged to the budget ledger.
    """

    name = "score"

    @staticmethod
    def _adapter(tier: int) -> Adapter:
        if tier not in (0, 1, 2):
            raise ValueError(f"tier must be 0, 1 or 2 (got {tier!r})")
        keys = {
            0: "score.tier0.rdkit",
            1: "score.tier1.surrogate",
            2: "score.tier2.pyscf",
        }
        return registry.get(keys[tier])

    def score(
        self, manifest, budget, candidates: List[Candidate], tier: int = 0
    ) -> Bundle:
        return self._adapter(tier).run(manifest, budget, candidates=candidates)


class OptimizeService:
    """OpenEvolve-backed evolutionary optimization — the engine of the platform.

    ``initial_program`` — the seed the loop starts from (generator function or
    candidate list). ``evaluator`` — a ``Callable[[Candidate], ScoreVector]``
    (typically via :class:`ScoreService`) or a registered evaluator name.
    """

    name = "optimize"

    def evolve(
        self,
        manifest,
        budget,
        initial_program: Any,
        evaluator: Any,
        iterations: int = 10,
        **kw,
    ) -> Bundle:
        adapter = registry.get("optimize.openevolve")
        return adapter.run(
            manifest,
            budget,
            initial_program=initial_program,
            evaluator=evaluator,
            iterations=iterations,
            **kw,
        )


def services() -> Dict[str, Any]:
    """All four facades in one dict: ``services()["score"].score(...)``."""
    return {
        "structure": StructureService(),
        "design": DesignService(),
        "score": ScoreService(),
        "optimize": OptimizeService(),
    }


__all__ = [
    "StructureService",
    "DesignService",
    "ScoreService",
    "OptimizeService",
    "services",
]
