{"content": """"Service facades — the single public entry layer.

Each facade is a thin object that (1) owns a Budget, (2) pulls the right
adapter from :data:`opensciencelab.base.registry`, (3) calls it through the
:class:`opensciencelab.manifest.Manifest` so every side-effect is recorded, and
(4) returns the :class:`~opensciencelab.base.Bundle`. Nothing else in the
package should bypass this layer — that is the rule that keeps the stack
auditable and model-swappable.

Usage::

    from opensciencelab.services import default_services

    svc = default_services()
    bundle = svc.score(
        candidates=[Candidate(id="c1", kind="molecule", smi="c1ccccc1O")],
        tier=0,
    )
    print(bundle.artifacts[0].payload["scores"])

The ``runs/`` directory defaults to ``./runs`` inside the current working
directory; override with ``Manifest(run_id=..., seed=..., run_dir=...)``.
"""
from __future__ import annotations

from typing import Any, Callable, Dict, List, Optional

from .base import (
    TIER_ZERO,
    TIER_ONE,
    TIER_TWO,
    Adapter,
    Artifact,
    Bundle,
    Budget,
    Candidate,
    ScoreVector,
    budget_default,
    registry,
)
from .manifest import Manifest


# --------------------------------------------------------------------------- #
# Facade                                                                      #
# --------------------------------------------------------------------------- #
class _Service:
    """Common plumbing shared by all four service facades."""

    def __init__(
        self,
        manifest: Manifest,
        budget: Optional[Budget] = None,
    ):
        self.manifest = manifest
        self.budget = budget or budget_default()

    def _call(self, adapter_name: str, **inputs: Any) -> Bundle:
        adapter = registry.get(adapter_name)
        if isinstance(adapter, KeyError) or adapter is None:
            try:
                adapter = registry.get(adapter_name.split(".")[1] + "." + adapter_name.split(".")[-1])
            except Exception:
                raise KeyError(
                    f"adapter '{adapter_name}' is not registered; "
                    f"available: {sorted(registry._adapters)}"
                ) from None
        call_record = {
            "service": adapter.name,
            "inputs_keys": sorted(inputs.keys()),
            "budget_snapshot": {
                "remaining": self.budget.remaining_per_tier(),
            },
        }
        manifest = self.manifest
        manifest.begin_call(call_record)

        bundle: Optional[Bundle] = None
        try:
            budget_snapshot = self.budget.snapshot()
            bundle = adapter.call(
                manifest,
                self.budget,
                manifest=manifest,
                budget=self.budget,
                **inputs,
            )
            self.budget.charge(bundle.cost)
        except BaseException as e:
            manifest.record_error(f"{adapter_name} failed: {type(e).__name__}: {e}")
            raise
        finally:
            bundle = bundle or Bundle(artifacts=[], cost={})
            for cost_tier, v in bundle.cost.items():
                self.budget.charge({cost_tier: v})
            manifest.finish_call(bundle=bundle)
        return bundle


# --------------------------------------------------------------------------- #
# Public facades                                                              #
# --------------------------------------------------------------------------- #
class StructureService(_Service):
    def predict(
        self,
        input_: Any,
        model: str = "boltz2",
        budget: Optional[Budget] = None,
    ) -> Bundle:
        adapter_name = {
            "boltz2": "structure.boltz2",
            "chai1": "structure.chai1",
            "esmfold": "structure.esmfold",
        }.get(model)
        if adapter_name is None:
            raise ValueError(f"unknown structure model '{model}'")
        return self._call(adapter_name, input_=input_)

    def predict_dual(self, input_: Any) -> Dict[str, Bundle]:
        """Compare Boltz-2 and Chai-1 on the same input; record both artifacts."""
        return {"boltz2": self.predict(input_, model="boltz2"),
                "chai1": self.predict(input_, model="chai1")}


class DesignService(_Service):
    def design(self, target_structure: Any, n_seqs: int = 5) -> Bundle:
        return self._call("design.rfmpnn", target_structure=target_structure, n_seqs=n_seqs)


class ScoreService(_Service):
    def score(
        self,
        candidates: List[Candidate],
        tier: int = TIER_ZERO,
    ) -> Bundle:
        if tier not in (TIER_ZERO, TIER_ONE, TIER_TWO):
            raise ValueError("tier must be 0, 1, or 2")
        adapter_name = {
            TIER_ZERO: "score.tier0.rdkit",
            TIER_ONE: "score.tier1.surrogate",
            TIER_TWO: "score.tier2.pyscf",
        }[tier]
        return self._call(adapter_name, candidates=candidates)

    def score_staged(
        self,
        candidates: List[Candidate],
        tier1_budget: int = 20,
        tier2_budget: int = 5,
    ) -> Dict[str, Any]:
        """The canonical staged pipeline: tier-0 on everyone, tier-1 on the top
        ``tier1_budget``, tier-2 on the top ``tier2_budget``. Tier budgets are
        enforced through :class:`Budget`."""
        from .base import Candidate as _C

        t0_raw = self.score(candidates, tier=TIER_ZERO).artifacts[0].payload["scores"]
        t0 = [
            (r, _C(id=r["candidate_id"], kind="molecule", smi="", seq=""))
            for r in t0_raw
        ]
        t0.sort(key=lambda p: -sum(v for v in p[0]["metrics"].values()))
        top1 = t0[:tier1_budget]
        if top1:
            t1_raw = self.score(
                [self._lookup(candidates, r["candidate_id"]) for r, _ in top1],
                tier=TIER_ONE,
            ).artifacts[0].payload["scores"]
            t1 = [
                (r, self._lookup(candidates, r["candidate_id"])) for r in t1_raw
            ]
            t1.sort(key=lambda p: -sum(v for v in p[0]["metrics"].values()))
            top2 = t1[:tier2_budget]
        else:
            t1, top2 = [], []
        t2_raw = None
        if top2:
            t2_raw = self.score(
                [self._lookup(candidates, r["candidate_id"]) for r, _ in top2],
                tier=TIER_TWO,
            ).artifacts[0].payload["scores"]
        return {
            "tier0_scores": [p[0] for p in t0],
            "tier1_scores": [p[0] for p in t1],
            "tier2_scores": t2_raw,
        }

    @staticmethod
    def _lookup(cands: List[Candidate], cid: str) -> Candidate:
        for c in cands:
            if c.id == cid:
                return c
        return Candidate(id=cid, kind="molecule", smi="", seq="")


class OptimizeService(_Service):
    def optimize(
        self,
        initial_program: Any,
        evaluator: Callable[[Candidate], ScoreVector],
        iterations: int = 10,
        population: int = 8,
        islands: int = 2,
        max_evals: int = 200,
        **kw,
    ) -> Bundle:
        return self._call(
            "optimize.openevolve",
            initial_program=initial_program,
            evaluator=evaluator,
            iterations=iterations,
            population=population,
            islands=islands,
            max_evals=max_evals,
            **kw,
        )


# --------------------------------------------------------------------------- #
# Factory                                                                     #
# --------------------------------------------------------------------------- #
def default_services(
    run_id: Optional[str] = None,
    seed: int = 1337,
    run_dir: str = "runs",
    budgets: Optional[Dict[int, float]] = None,
) -> Dict[str, _Service]:
    """Build all four facades sharing one manifest + budget ledger."""
    import os

    os.makedirs(run_dir, exist_ok=True)
    manifest = Manifest(run_id=run_id, seed=seed, run_dir=run_dir)
    budget = Budget(budgets or {0: 1e9, 1: 200.0, 2: 500.0})
    common = dict(manifest=manifest, budget=budget)
    return {
        "structure": StructureService(**common),
        "design": DesignService(**common),
        "score": ScoreService(**common),
        "optimize": OptimizeService(**common),
    }


__all__ = [
    "StructureService",
    "DesignService",
    "ScoreService",
    "OptimizeService",
    "default_services",
]
