import hashlib
import json
import time
import uuid
from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Optional

from .manifest import Budget, BudgetExceeded, budget_default  # noqa: F401  (re-export)


def _now() -> str:
