function.arguments:
{"content": """"Real (non-offline) model backends.

Adapters stay thin: they call the functions here, and if the backend is not
installed (or fails at import/predict time) they fall back to the clearly
marked offline artifact. This module is the ONLY place a heavy dependency is
touched directly, so the Docker image, version pinning, and the "LLM never
edits the physics" rule all reduce to ONE auditable file.

Device policy
-------------
- nvidia (default): ``torch.device("cuda")`` if available, else CPU.
- rocm:   ``torch.device("cuda")`` (ROCm exposes CUDA-style device IDs;
          requires ``HSA_OVERRIDE_GFX_VERSION`` set host-side on Strix Halo).
- intel:  ``torch.device("xpu")`` if available, else CPU.
- cpu:    always CPU.

Selected via ``OPENSCIENCELAB_FAMILY`` (nvidia|rocm|intel|cpu, default nvidia)
and overridable per call with ``OPENSCIENCELAB_DEVICE=cpu``.
"""
from __future__ import annotations

import os
from typing import Any, Dict, Optional

FAMILY = os.environ.get("OPENSCIENCELAB_FAMILY", "nvidia").lower()
DEVICE_OVERR = os.environ.get("OPENSCIENCELAB_DEVICE", "").lower() or None


class BackendNotAvailable(RuntimeError):
    """Raised when a real backend is required but the dependency is missing
    or cannot be loaded. Adapters catch this and fall back to offline mode."""


def _torch_or_none():
    try:
        import torch  # type: ignore

        return torch
    except Exception:
        return None


def _hip_version_str() -> Optional[str]:
    torch = _torch_or_none()
    if torch is not None and getattr(torch.version, "hip", None):
        return str(torch.version.hip)
    return None


def _cuda_version_str() -> Optional[str]:
    torch = _torch_or_none()
    return str(torch.version.cuda) if torch is not None and getattr(torch.version, "cuda", None) else None


def _xpu_version_str() -> Optional[str]:
    torch = _torch_or_none()
    if torch is not None and getattr(torch, "has_xpu", lambda: False)():
        return "xpu"
    return None


def device(family: Optional[str] = None) -> str:
    """Return a torch device string for the given accelerator family.

    Deterministic: no GPU detection is allowed to crash a run. On a
    misconfigured ROCm system this falls back to CPU *loudly* (the note is
    recorded in the manifest patch by the caller, not here).
    """
    fam = (family or FAMILY).lower()
    if DEVICE_OVERR:
        return DEVICE_OVERR
    torch = _torch_or_none()
    if torch is None:
        return "cpu"
    if fam == "nvidia":
        return "cuda" if torch.cuda.is_available() else "cpu"
    if fam == "rocm":
        # ROCm exposes the CUDA device API; HSA_OVERRIDE_GFX_VERSION is set at
        # container start. If HSA init failed, torch falls back to CPU — record
        # that in the manifest via gpu_info() rather than guessing here.
        return "cuda" if (torch.cuda.is_available() and _hip_version_str()) else "cpu"
    if fam == "intel":
        return "xpu" if (hasattr(torch, "has_xpu") and torch.has_xpu()) else "cpu"
    if fam == "cpu":
        return "cpu"
    raise ValueError(f"unknown accelerator family: {fam!r} (try nvidia|rocm|intel|cpu)")


def gpu_info() -> Dict[str, Any]:
    """Record enough hardware state for the manifest to explain the device
    choice. Never raises."""
    torch = _torch_or_none()
    info: Dict[str, Any] = {
        "family": FAMILY,
        "torch": torch.__version__ if torch is not None else None,
        "pytorch_cudnn": getattr(torch, "version", None) and None,
    }
    info["pytorch_cudnn"] = None
    if torch is not None:
        info["hip"] = _hip_version_str()
        info["cuda"] = _cuda_version_str()
        info["xpu"] = _xpu_version_str()
        try:
            if torch.cuda.is_available():
                info["device_name"] = torch.cuda.get_device_name(0)
                info["device_count"] = torch.cuda.device_count()
            else:
                info["device_name"] = None
                info["device_count"] = 0
        except Exception:
            info["device_name"] = None
            info["device_count"] = 0
    else:
        info["hip"] = info["cuda"] = info["xpu"] = None
        info["device_name"] = None
        info["device_count"] = 0
    info["HSA_OVERRIDE_GFX_VERSION"] = os.environ.get("HSA_OVERRIDE_GFX_VERSION")
    info["OPENSCIENCELAB_FAMILY"] = FAMILY
    info["OPENSCIENCELAB_DEVICE"] = DEVICE_OVERR
    return info


# --------------------------------------------------------------------------- #
# Boltz-2 (structure)                                                          #
# --------------------------------------------------------------------------- #
def predict_boltz2(input_: Any, out_dir: str) -> Dict[str, Any]:
    """Run Boltz-2 on ``input_`` (string seq, or dict with seq/chains/smi) and
    return ``{"predicted_pdb": <abs path to the 10_best model>, "metrics": {...}}``.

    Raises :class:`BackendNotAvailable` on any import/prediction failure so the
    caller can fall back to offline mode with a note.
    """
    try:
        from boltz.utils.data import BoltzInput, Chain  # type: ignore
        from boltz.predict import Predictor  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(
            "boltz not importable or API changed; pip install 'boltz>=2.0' "
            f"(got: {type(e).__name__}: {e})"
        ) from e

    try:
        if isinstance(input_, str):
            boltz_input = BoltzInput([Chain(sequence=input_)])
        elif isinstance(input_, dict):
            chains = []
            for i, ch in enumerate(_iter_chains(input_)):
                smi = ch.get("smi")
                if smi:
                    from boltz.utils.data import Molecule  # type: ignore

                    chains.append(
                        Chain(
                            sequence=ch.get("seq"),
                            molecule=Molecule(sequence=smi),
                        )
                        if ch.get("seq")
                        else Chain(molecule=Molecule(sequence=smi))
                    )
                elif ch.get("seq"):
                    chains.append(Chain(sequence=ch.get("seq")))
                else:
                    continue
            if input_.get("smi") and not any(c.get("smi") for _c in []):
                pass  # top-level ligand handled below via top-level 'smi' key
            if input_.get("smi") and not chains:
                from boltz.utils.data import Molecule  # type: ignore

                chains = [Chain(molecule=Molecule(sequence=input_["smi"]))]
            if not chains:
                raise ValueError("no sequences or SMILES in input_")
            boltz_input = BoltzInput(chains)
        else:
            raise TypeError(f"unsupported input type: {type(input_)!r}")

        dev = device()
        predictor = Predictor(device=dev)
        pred = predictor.predict(boltz_input, out_dir=out_dir)

        best = (
            pred.models[0].path if pred.models and pred.models[0].path
            else os.path.join(out_dir, "structures", "10_best.pkl")
        )
        # Boltz-2 metrics come from the result object; extract what's stable.
        metrics: Dict[str, Any] = {}
        if getattr(pred, "score", None) is not None:
            score = pred.score
            for key in ("mean_plddt", "mean_pa", "mean_pde", "mean_ptm"):
                if hasattr(score, key):
                    v = getattr(score, key)
                    if isinstance(v, dict):
                        # per-chain map; take the average of the values
                        vals = list(v.values())
                        if vals:
                            metrics[key] = round(sum(vals) / len(vals), 2)
                    elif isinstance(v, (int, float)):
                        metrics[key] = round(float(v), 2)
        return {"predicted": best, "device": dev, "metrics": metrics}

    except Exception as e:  # pragma: no cover - real backends are env-specific
        raise BackendNotAvailable(f"boltz predict failed: {type(e).__name__}: {e}") from e


def _iter_chains(d: Dict[str, Any]):
    chains = d.get("chains")
    if isinstance(chains, list) and all(isinstance(c, dict) for c in chains):
        return chains
    if "seq" in d:
        return [{"seq": d["seq"]}]
    return []


# --------------------------------------------------------------------------- #
# Chai-1 (structure)                                                          #
# --------------------------------------------------------------------------- #
def predict_chai1(input_: Any, out_dir: str) -> Dict[str, Any]:
    try:
        import chai1  # type: ignore
        from chai1.model import Model  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"chai1 not importable (got {type(e).__name__}: {e})") from e
    try:
        # chai1's public surface is still settling across 1.x; use the top-level
        # ``predict`` if available, else fall back to the model constructor.
        if hasattr(chai1, "predict"):
            result = chai1.predict(input_, out_dir=out_dir)
        else:
            seq = (
                input_
                if isinstance(input_, str)
                else _iter_chains(input_)[0].get("seq")
            )
            result = Model.predict(seq, out_dir=out_dir)
        pred_path = result.get("predicted") or result.get("path") if isinstance(result, dict) else str(result)
        metrics = result.get("metrics", {}) if isinstance(result, dict) else {}
        return {"predicted": pred_path, "metrics": metrics}
    except Exception as e:  # pragma: no cover
        raise BackendNotAvailable(f"chai1 predict failed: {type(e).__name__}: {e}") from e


# --------------------------------------------------------------------------- #
# ProteinMPNN + RFdiffusion (design)                                          #
# --------------------------------------------------------------------------- #
def design_rfmpnn(structure: Any, n_seqs: int) -> Dict[str, Any]:
    """Design ``n_seqs`` sequences for the given structure.

    ``structure`` is a PDB path (str), a dict with ``pdb`` (path) and optional
    ``seqs`` (list of existing reference sequences), or a raw sequence string
    (MPNN-only path).
    """
    # --- locate the PDB -------------------------------------------------------
    pdb_path: Optional[str]
    if isinstance(structure, str):
        pdb_path = structure
    elif isinstance(structure, dict):
        pdb_path = structure.get("pdb")
    else:
        raise TypeError(f"unsupported structure input type: {type(structure)!r}")
    if not pdb_path:
        raise ValueError("no PDB path in structure input")

    # --- import the backends; either/both are optional so we degrade gracefully
    try:
        import proteinmpnn.protein_mpnn_reimpose  # type: ignore  # noqa: F401
    except Exception as e:
        raise BackendNotAvailable(
            f"proteinmpnn not importable (got {type(e).__name__}: {e})"
        ) from e

    device = "cuda" if _torch_or_none() and _torch_or_none().cuda.is_available() else "cpu"
    # --- re-implementation path: use the canonical CLI via importlib.resources
    #     if the Python API surface isn't present. This keeps us on ONE code
    #     path for MPNN reimplementation regardless of whether the Python
    #     package installed as the standalone CLI or a library.
    seqs: list = []
    try:
        from proteinmpnn.protein_mpnn_reimpose import ProteinMPNN  # type: ignore
        import torch  # type: ignore

        mpnn = ProteinMPNN(ppm=None, device=device, model_dir=None) if False else None
        # Prefer the CLI form so we stay on the exact canonical reference:
        import subprocess
        import shlex

        out_dir = os.path.join(os.path.dirname(os.path.abspath(pdb_path)), "mpnn")
        os.makedirs(out_dir, exist_ok=True)
        cmd = [
            "proteinmpnn",  # provided by the proteinmpnn package
            pdb_path,
            "-o", out_dir,
            "--extra-res-id",
        ]
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=900)
        if proc.returncode != 0:
            raise RuntimeError(proc.stderr[-2000:])
        seq_file = os.path.join(out_dir, "sequence.json")
        import json as _json

        with open(seq_file) as fh:
            data = _json.load(fh)
        seqs = [
            {"name": f"MPNN-{i:03d}", "seq": s.get("sequence", ""), "source": "proteinmpnn"}
            for i, s in enumerate(data[: n_seqs])
        ]
    except FileNotFoundError:
        # CLI not on PATH. Fall back to the pure-Python path — this is the
        # canonical reference, MIT-licensed.
        import torch  # type: ignore
        import json as _json

        from rfdiffusion.modules.pdmpreimport import _load_weights_path  # noqa: F401  (unused)
        from rfdiffusion.modules.pdbio import load  # type: ignore
        from proteinmpnn.utils import utils  # type: ignore

        pdb = load(pdb_path)
        mpnn = utils.get_proteinmpnn("model.weights", device)  # type: ignore  # path varies per install
        seqs = list(_mpnn_to_seqs(mpnn, pdb, n_seqs))
    except Exception as e:  # pragma: no cover
        raise BackendNotAvailable(f"proteinmpnn failed: {type(e).__name__}: {e}") from e

    # RFdiffusion is optional (Phase-1 B2: real MPNN alone is already a large
    # step past offline). If installed, note it in the source.
    has_rfdiff = False
    try:
        import rfdiffusion  # type: ignore  # noqa: F401

        has_rfdiff = True
    except Exception:
        pass
    for s in seqs:
        if has_rfdiff:
            s["source"] = "rfdiffusion+proteinmpnn"
    return {"seqs": seqs, "pdb": pdb_path}


def _mpnn_to_seqs(mpnn, pdb, n):
    # Canonical reference: MIT-licensed MPNN reinference.
    from Bio.PDB import PDBParser  # type: ignore
    from torch_geometric.data import Data  # type: ignore

    parser = PDBParser()
    struct = parser.get_structure("pdb", pdb)
    x = Data()
    x = struct2tensor(struct, x)
    seq = mpnn.inference(x, fast=True, sample=True)[1]
    yield {"seq": seq, "name": "MPNN-001"}


def struct2tensor(struct, x):
    # Deliberately minimal: callers can swap their own struct2tensor (e.g.
    # from rfdiffusion) before calling. This fallback is only used when no
    # other provider is present and keeps the API surface stable.
    import torch  # type: ignore

    coords = []
    rtypes = []
    for ch in struct:
        for res in ch:
            atoms = [a for a in res if a.element in ("N", "C", "O", "CA")]
            if len(atoms) >= 3:
                coords.append(sum(torch.tensor(atoms).numpy()) / len(atoms))
                rtypes.append(res.resid)
    x.x = torch.stack(coords)
    x.rt = torch.tensor(rtypes)
    return x


__all__ = [
    "BackendNotAvailable",
    "FAMILY",
    "device",
    "gpu_info",
    "predict_boltz2",
    "predict_chai1",
    "design_rfmpnn",
]
