"""Shared types, the Adapter contract, and the registry.

Design rule: every capability (structure, design, scoring, optimization) is an
:class:`Adapter`. Everything funnels through :meth:`Adapter.run`, which
charges the budget, stamps artifacts, and records the call on the run
manifest. That single choke point is what makes provenance and budgeting
trivial.

Re-exports from :mod:`.manifest` (``Budget``, ``budget_default``,
``BudgetExceeded``) so a service can import one module.
"""
from __future__ import annotations

import hashlib
import json
import time
import uuid
from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Optional

from .manifest import Budget, BudgetExceeded, Manifest, RunDirectory, budget_default  # noqa: F401  (re-export)


def _now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


# --------------------------------------------------------------------------- #
# Cost model: tiered compute                                                  #
# --------------------------------------------------------------------------- #
# Higher tier = slower / more expensive, used on fewer candidates. Costs are
# abstract "units" (not $); a Budget maps them to real cost as needed.
TIER_ZERO, TIER_ONE, TIER_TWO = 0, 1, 2


# --------------------------------------------------------------------------- #
# Core data types                                                             #
# --------------------------------------------------------------------------- #
@dataclass
class Candidate:
    """A thing being scored (molecule / complex / crystal)."""

    id: str
    kind: str = "molecule"  # molecule | complex | crystal
    smi: Optional[str] = None
    pdb_id: Optional[str] = None
    seq: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Candidate":
        d = dict(d)
        d.setdefault("metadata", {})
        allowed = {k: d[k] for k in ("id", "kind", "smi", "pdb_id", "seq", "metadata") if k in d}
        return cls(**allowed)


@dataclass
class ScoreVector:
    """Named metric values for a candidate.

    Convention: **higher is better** for every key. A scoring adapter flips the
    sign of naturally "lower-better" metrics (e.g. docking energy) beforehand.
    """

    metrics: Dict[str, float] = field(default_factory=dict)
    tier: int = TIER_ZERO
    notes: Dict[str, Any] = field(default_factory=dict)

    def get(self, name: str, default: float = 0.0) -> float:
        return self.metrics.get(name, default)

    def to_dict(self) -> Dict[str, Any]:
        return {"tier": self.tier, "metrics": self.metrics, "notes": self.notes}

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "ScoreVector":
        return cls(
            metrics=dict(d.get("metrics", {})),
            tier=d.get("tier", TIER_ZERO),
            notes=dict(d.get("notes", {})),
        )


@dataclass
class Artifact:
    """An immutable product of an adapter call, with a stable digest."""

    id: str = ""
    kind: str = ""  # structure | design_seqs | scores | pareto | report | ...
    service: str = ""
    service_version: str = ""
    created_at: str = ""
    payload: Dict[str, Any] = field(default_factory=dict)
    files: List[str] = field(default_factory=list)  # relative paths under run dir

    def digest(self) -> str:
        blob = json.dumps(
            {
                "id": self.id,
                "kind": self.kind,
                "service": self.service,
                "service_version": self.service_version,
                "payload": self.payload,
            },
            sort_keys=True,
            default=str,
        ).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()[:16]

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["digest"] = self.digest()
        return d


@dataclass
class Bundle:
    """What every adapter returns: artifacts, manifest patch, cost by tier."""

    artifacts: List[Artifact] = field(default_factory=list)
    manifest_patch: Dict[str, Any] = field(default_factory=dict)
    cost: Dict[int, float] = field(
        default_factory=lambda: {TIER_ZERO: 0.0, TIER_ONE: 0.0, TIER_TWO: 0.0}
    )

    def total_cost(self) -> float:
        return sum(self.cost.values())


# --------------------------------------------------------------------------- #
# Adapter contract                                                            #
# --------------------------------------------------------------------------- #
class Adapter(ABC):
    """Base class for all services.

    Subclasses set ``name`` and ``version`` and implement :meth:`_exec`.
    :meth:`run` adds the boilerplate: charging the budget, stamping artifacts,
    and recording the call against the run manifest.
    """

    name: str = "adapter"
    version: str = "0.0.1"

    @abstractmethod
    def _exec(self, manifest, budget, **inputs) -> Bundle:
        raise NotImplementedError

    def run(self, manifest, budget, **inputs) -> Bundle:
        bundle = self._exec(manifest, budget, **inputs)

        # charge the budget for each tier used (validates per-tier limits)
        if budget is not None:
            for tier, cost in bundle.cost.items():
                budget.spend(int(tier), float(cost))

        # stamp artifacts with this service's identity
        for art in bundle.artifacts:
            if not art.service:
                art.service = self.name
            if not art.service_version:
                art.service_version = self.version
            if not art.created_at:
                art.created_at = _now()
            if not art.id:
                art.id = new_id(art.kind)
            manifest.attach_artifact(art.to_dict(), list(art.files))

        # record the call (stable signature enables drift detection)
        manifest.record(
            service=self.name,
            version=self.version,
            call={k: _jsonable(v) for k, v in inputs.items()},
            cost=bundle.cost,
            artifacts=[a.id for a in bundle.artifacts],
        )
        manifest.merge_patch(bundle.manifest_patch)
        return bundle


def _jsonable(v: Any) -> Any:
    if isinstance(v, dict):
        return {str(k): _jsonable(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return [_jsonable(x) for x in v]
    if isinstance(v, (str, int, float, bool)) or v is None:
        return v
    if isinstance(v, Candidate):
        return v.to_dict()
    if isinstance(v, ScoreVector):
        return v.to_dict()
    return repr(v)


def new_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:10]}"


# --------------------------------------------------------------------------- #
# Registry                                                                    #
# --------------------------------------------------------------------------- #
class _Registry:
    """Name -> Adapter instance. Adapters self-register on import."""

    def __init__(self) -> None:
        self._adapters: Dict[str, Adapter] = {}

    def register(self, adapter: Adapter) -> None:
        existing = self._adapters.get(adapter.name)
        if existing is not None and existing.version != adapter.version:
            raise ValueError(
                f"adapter {adapter.name!r} already registered at "
                f"{existing.version!r}; refusing to overwrite"
            )
        self._adapters[adapter.name] = adapter

    def get(self, name: str) -> Adapter:
        if name not in self._adapters:
            raise KeyError(
                f"adapter {name!r} not registered. "
                f"Available: {self.available() or '<none>'}. "
            )
        return self._adapters[name]

    def available(self) -> List[str]:
        return sorted(self._adapters)

    def __contains__(self, name: str) -> bool:
        return name in self._adapters

    def __len__(self) -> int:
        return len(self._adapters)


registry = _Registry()

{"path": "opensciencelab/opensciencelab/manifest.py", "start_line": 140, "end_line": 303, "total_lines": 303, "content": "        # Manifest(seed=..., seeds={"structure": 42, "design": 43, ...}))
        for k in ("structure", "design", "score_tier2", "optimize"):
            self.seeds.setdefault(k, seed)
        self.env = _env_snapshot()
        self.calls: List[Dict[str, Any]] = []
        self.artifacts: List[Dict[str, Any]] = []
        self.errors: List[str] = []
        self.extra = extra or {}
        self.budget = budget
        self._pending_call: Optional[Dict[str, Any]] = None
        self._run_dir = RunDirectory(run_root, run_id)
        self._run_dir.ensure()

    # ---- run dir access ---------------------------------------------------------
    @property
    def run_dir(self) -> str:
        """Absolute path to ``runs/<id>``. Stable across saves/replays."""
        return self._run_dir.root

    # ---- call bookkeeping ----------------------------------------------------
    def begin_call(self, info: Dict[str, Any]) -> None:
        self._pending_call = dict(info)

    def finish_call(self, bundle: Any) -> None:
        # ``adapter.run`` has already recorded the call; nothing extra to persist.
        self._pending_call = None

    def record_error(self, message: str) -> None:
        self.errors.append(f"{_now()} {message}")

    # ---- streaming jsonl ------------------------------------------------------
    def append_jsonl(self, rel: str, obj: Dict[str, Any]) -> None:
        self._run_dir.append_jsonl(rel, obj)

    # ---- mutation --------------------------------------------------------------
    def record(
        self,
        *,
        service: str,
        version: str,
        call: Dict[str, Any],
        cost: Dict[int, float],
        artifacts: List[str],
    ) -> None:
        # Hash a canonical summary of the call so replays can verify no drift.
        sig = hashlib.sha256(
            json.dumps(
                {
                    "service": service,
                    "version": version,
                    "call": _json_stable(call),
                },
                sort_keys=True,
                default=str,
            ).encode("utf-8")
        ).hexdigest()
        self.calls.append(
            {
                "seq": len(self.calls),
                "service": service,
                "version": version,
                "call": call,
                "cost": {str(k): v for k, v in cost.items()},
                "artifact_ids": artifacts,
                "signature": sig,
                "at": _now(),
            }
        )
        self._pending_call = None

    def merge_patch(self, patch: Dict[str, Any]) -> None:
        """Merge an adapter's manifest patch (shallow dict)."""
        for k, v in (patch or {}).items():
            self.extra[k] = v

    def attach_artifact(self, art_dict: Dict[str, Any], files: List[str]) -> None:
        self.artifacts.append(art_dict)
        for f in files:
            self.extra.setdefault("files", []).append(f)

    # ---- persistence --------------------------------------------------------------
    def to_dict(self) -> Dict[str, Any]:
        return {
            "schema_version": SCHEMA_VERSION,
            "run_id": self.run_id,
            "purpose": self.purpose,
            "created_at": self.created_at,
            "seed": self.seed,
            "seeds": self.seeds,
            "env": self.env,
            "calls": self.calls,
            "artifacts": self.artifacts,
            "errors": self.errors,
            "extra": self.extra,
            "budget": self.budget.to_dict() if self.budget is not None else None,
        }

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), indent=2, sort_keys=True, default=str)

    def save(self) -> str:
        """Persist manifest.json + one file per artifact. Returns the run dir."""
        self._run_dir.write_text("manifest.json", self.to_json())
        for a in self.artifacts:
            aid = a.get("id") or "artifact"
            self._run_dir.write_text(
                f"artifacts/{aid}.json",
                json.dumps(a.get("payload", {}), indent=2, sort_keys=True, default=str),
            )
        return self._run_dir.root


def _json_stable(obj: Any) -> Any:
    """Recursively coerce to JSON-safe primitives (for stable hashing)."""
    if isinstance(obj, dict):
        return {str(k): _json_stable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_json_stable(v) for v in obj]
    if isinstance(obj, (str, int, float, bool)) or obj is None:
        return obj
    return str(obj)


# --------------------------------------------------------------------------- #
# Run directory                                                                 #
# --------------------------------------------------------------------------- #
class RunDirectory:
    """Thin file helper so the layout is enforced in ONE place.

    Layout::

        runs/<id>/
          manifest.json
          artifacts/<artifact_id>.json
          candidates.jsonl
          scores.jsonl
          report.md
          inputs/
    """

    def __init__(self, root: str, run_id: str) -> None:
        self.run_id = run_id
        self.root = os.path.join(root, run_id)

    def path(self, *parts) -> str:
        p = os.path.join(self.root, *parts)
        return os.path.normpath(p)

    def ensure(self) -> None:
        os.makedirs(self.path("artifacts"), exist_ok=True)
        os.makedirs(self.path("inputs"), exist_ok=True)

    def write_text(self, rel: str, text: str) -> str:
        p = self.path(rel)
        os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
        with open(p, "w", encoding="utf-8") as fh:
            fh.write(text)
        return p

    def append_jsonl(self, rel: str, obj: Dict[str, Any]) -> None:
        p = self.path(rel)
        os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
        with open(p, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(obj, sort_keys=True, default=str) + "\n")"}

